{
  "id": "R1",
  "summary_ko": "로봇이 한 발만 드는 것이 아니라 양발을 모두 들어 올린다.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "The robot lifts both feet, not just one.",
      "symptom_ko": "로봇이 한 발만 드는 것이 아니라 양발을 동시에 들어 올림",
