  "claims": [
    {
      "id": "R3.S1",
      "evidence": "Robot doesn't lift his foot as his foot is already up to begin the video",
      "symptom_ko": "영상 시작 시점에 발이 이미 들려 있어서 로봇이 발을 들어올리지 않음",
